  ('masjid-5311'),
  ('masjid-e-quba-0204'),
  ('masjid-e-rehmat-0114'),
  ('peer-mehr-ali-shah-masjid-5700'),
  ('prayer-area-2352')
on conflict (place_id) do nothing;
